css:
/* 赛博都市：昼夜双版（:root 为日间基线，[data-reader-theme="night"] 覆盖夜景）；正文区占页高 80%+（蓝图硬约束①） */
:root{
  --cc-bg:#f5f6fa; --cc-fg:#1a1e2b; --cc-dim:#616b80;
  --cc-neon:#0e7490; --cc-neon2:#a21caf; --cc-sky:rgba(14,116,144,.20); --cc-line:rgba(14,116,144,.26);
}
[data-reader-theme="night"]{
  --cc-bg:#07080f; --cc-fg:#e6ebff; --cc-dim:#8b95b0;
  --cc-neon:#22d3ee; --cc-neon2:#e879f9; --cc-sky:rgba(34,211,238,.22); --cc-line:rgba(34,211,238,.30);
}
html,body{margin:0;padding:0;background:var(--cc-bg);color:var(--cc-fg);
  font-family:-apple-system,"Noto Sans CJK SC","Source Han Sans SC",sans-serif;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.8);}
body::before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.55;
  background-image:linear-gradient(var(--cc-line) 1px,transparent 1px),linear-gradient(90deg,var(--cc-line) 1px,transparent 1px);
  background-size:100% 34px,34px 100%;
  -webkit-mask-image:radial-gradient(120% 60% at 50% 0,#000,transparent 72%);mask-image:radial-gradient(120% 60% at 50% 0,#000,transparent 72%);}
.cc-head{position:relative;display:flex;justify-content:space-between;align-items:baseline;gap:.6em;
  padding:.6em 1.05em .45em;font-size:.76em;letter-spacing:.14em;color:var(--cc-dim);}
.cc-chapter{max-width:72%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.cc-pct{color:var(--cc-neon);font-variant-numeric:tabular-nums;}
.cc-sky{position:relative;padding:.7em 1.05em 7vh;overflow:hidden;}
.cc-sky::after{content:"";position:absolute;left:0;right:0;bottom:0;height:7vh;
  background:repeating-linear-gradient(90deg,transparent 0 6px,rgba(255,255,255,.55) 6px 7px),
    linear-gradient(90deg,
      var(--cc-sky) 0 7%,transparent 7% 9%,
      var(--cc-sky) 9% 19%,transparent 19% 21%,
      var(--cc-sky) 21% 34%,transparent 34% 36%,
      var(--cc-sky) 36% 44%,transparent 44% 47%,
      var(--cc-sky) 47% 62%,transparent 62% 64%,
      var(--cc-sky) 64% 73%,transparent 73% 76%,
      var(--cc-sky) 76% 88%,transparent 88% 90%,
      var(--cc-sky) 90% 100%);
  -webkit-mask-image:linear-gradient(180deg,transparent,#000 42%);mask-image:linear-gradient(180deg,transparent,#000 42%);}
.cc-city{position:relative;z-index:1;display:block;font-size:1.6em;font-weight:800;letter-spacing:.1em;
  text-shadow:0 0 14px var(--cc-neon);}
.cc-city-sub{position:relative;z-index:1;display:block;margin-top:.2em;font-size:.74em;letter-spacing:.46em;color:var(--cc-dim);}
.cc-body{position:relative;padding:.8em 1.15em 0;}
.cc-body .reader-chapter-title{margin:0 0 .7em;font-size:1.36em;font-weight:700;}
.cc-body .reader-paragraph{margin:0 0 .9em;text-indent:2em;}
.cc-body p{margin:0 0 .9em;}
.cc-body a{color:var(--cc-neon2);text-decoration:none;border-bottom:1px solid var(--cc-line);}
.cc-body blockquote{margin:0 0 1em;padding:.5em .95em;border-left:2px solid var(--cc-neon2);color:var(--cc-dim);
  background:linear-gradient(90deg,var(--cc-sky),transparent 70%);}
.cc-body code{background:rgba(127,127,127,.16);padding:.14em .36em;border-radius:3px;}
.cc-body pre{background:rgba(127,127,127,.12);padding:.85em;border-radius:5px;overflow-x:auto;border:1px solid var(--cc-line);}
.cc-body table{width:100%;border-collapse:collapse;}
.cc-body th,.cc-body td{border:1px solid var(--cc-line);padding:.34em .55em;}
.cc-foot{position:relative;display:flex;justify-content:space-between;gap:.8em;
  padding:.55em 1.15em .75em;font-size:.72em;color:var(--cc-dim);font-variant-numeric:tabular-nums;
  border-top:1px solid var(--cc-line);}
@media (prefers-reduced-motion:reduce){.cc-city{text-shadow:none;}}

javascript:
(function () {
  'use strict';
  // 每页动效。只使用双方共有的 readerTemplate 钩子 API + Web Animations
  // => 同一份主题在我们与 archive 两个引擎上行为一致（互兼容目标）。
  var anims = [], active = null;
  function stop() {
    for (var i = 0; i < anims.length; i++) { anims[i].cancel(); }
    anims = []; active = null;
  }
  function play(node, frames, dur, delay, easing) {
    if (!node || typeof node.animate !== 'function') return;
    anims.push(node.animate(frames, {
      duration: dur, delay: delay || 0, iterations: Infinity, easing: easing || 'ease-in-out'
    }));
  }
  function all(root, sel) {
    return root ? Array.prototype.slice.call(root.querySelectorAll(sel)) : [];
  }
  function start(page) {
    active = page;
    // 小视口不做装饰动效（与 archive 主题同判据，避免小窗下动效抢帧）
    if (readerTemplate.viewport.height <= 440) return;
    var i;

    // 赛博都市：天幕明暗 + 副题呼吸 + 城市轮廓缓移
    play(page.querySelector('.cc-sky'), [{ opacity: 0.75 }, { opacity: 1 }, { opacity: 0.75 }], 6400);
    var tags = all(page, '.cc-city-sub, .cc-pct');
    for (i = 0; i < tags.length; i++) {
      play(tags[i], [{ opacity: 0.4 }, { opacity: 1 }, { opacity: 0.4 }], 2100 + i * 520, -i * 700);
    }
    play(page.querySelector('.cc-city'), [{ transform: 'translateX(0)' }, { transform: 'translateX(-5px)' }, { transform: 'translateX(0)' }], 9000);
  }
  // 结算后旧节点可能已脱离文档 => 先停旧动画（换壳/重排后由 motionChange 重新起）
  readerTemplate.on('afterLayout', function () { stop(); });
  readerTemplate.on('motionChange', function (event) {
    if (!event.page || event.state === 'settled' || event.reducedMotion) { stop(); return; }
    if (event.state === 'paused') {
      for (var i = 0; i < anims.length; i++) { anims[i].pause(); }
      return;
    }
    if (active === event.page) {
      for (var j = 0; j < anims.length; j++) { anims[j].play(); }
      return;
    }
    stop(); start(event.page);
  });
  readerTemplate.on('dispose', stop);
})();
